<div class="inventory-actions">
    <form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="content"><input type="hidden" name="content_type" value="<?= e($contentType) ?>"><input type="hidden" name="content_action" value="toggle"><input type="hidden" name="id" value="<?= $rowId ?>"><button class="text-button" type="submit">تبديل النشر</button></form>
    <form method="post" data-confirm="حذف هذا المحتوى نهائيًا؟"><?= csrf_field() ?><input type="hidden" name="kind" value="content"><input type="hidden" name="content_type" value="<?= e($contentType) ?>"><input type="hidden" name="content_action" value="delete"><input type="hidden" name="id" value="<?= $rowId ?>"><button class="text-button" type="submit">حذف</button></form>
</div>
<details class="inventory-edit"><summary>تعديل التفاصيل</summary>
    <?php $nameField = $contentType === 'scholar' ? 'name' : 'title'; $descriptionField = $contentType === 'scholar' ? 'biography' : 'description'; ?>
    <form class="form-stack" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="kind" value="content"><input type="hidden" name="content_type" value="<?= e($contentType) ?>"><input type="hidden" name="content_action" value="update"><input type="hidden" name="id" value="<?= $rowId ?>">
        <label><?= $contentType === 'scholar' ? 'الاسم' : 'العنوان' ?><input name="<?= e($nameField) ?>" maxlength="<?= $contentType === 'scholar' ? '180' : '240' ?>" value="<?= e((string) $row[$nameField]) ?>" required></label>
        <?php if ($contentType === 'book'): ?><label>المؤلف<input name="author" maxlength="180" value="<?= e((string) $row['author']) ?>" required></label><?php endif; ?>
        <?php if ($contentType === 'book'): ?><label>كلمات مفتاحية<input name="keywords" maxlength="1000" value="<?= e((string) ($row['keywords'] ?? '')) ?>"></label><label>اللغة<select name="language"><option value="ar"<?= ($row['language'] ?? 'ar') === 'ar' ? ' selected' : '' ?>>العربية</option><option value="en"<?= ($row['language'] ?? '') === 'en' ? ' selected' : '' ?>>الإنجليزية</option><option value="other"<?= ($row['language'] ?? '') === 'other' ? ' selected' : '' ?>>أخرى</option></select></label><label>سنة النشر<input type="number" name="publication_year" min="1000" max="2200" value="<?= e((string) ($row['publication_year'] ?? '')) ?>"></label><label>صاحب الحقوق<input name="rights_holder" maxlength="180" value="<?= e((string) ($row['rights_holder'] ?? '')) ?>"></label><?php endif; ?>
        <?php if ($contentType !== 'adhkar'): ?><label><?= $contentType === 'scholar' ? 'نبذة' : 'الوصف' ?><textarea name="<?= e($descriptionField) ?>" maxlength="4000" rows="2"><?= e((string) ($row[$descriptionField] ?? '')) ?></textarea></label><?php endif; ?>
        <?php if ($contentType === 'adhkar'): ?><label>نص الذكر<textarea name="formula" maxlength="5000" rows="3" required><?= e((string) $row['formula']) ?></textarea></label><label>المرجع<input name="source_reference" maxlength="300" value="<?= e((string) $row['source_reference']) ?>" required></label><label>التصنيف<input name="category" maxlength="80" value="<?= e((string) $row['category']) ?>" required></label><label>التكرار<input type="number" name="repeat_count" min="1" max="1000" value="<?= e((string) ($row['repeat_count'] ?? '')) ?>"></label><label class="check-label"><input type="checkbox" name="reviewed" required<?= $row['is_reviewed'] ? ' checked' : '' ?>> تمت المراجعة</label><?php endif; ?>
        <label>رابط المصدر / الفيديو<input type="url" name="source_url" maxlength="500" value="<?= e((string) ($row['source_url'] ?? '')) ?>"<?= $contentType === 'series' ? '' : ' required' ?>></label>
        <?php if ($contentType === 'scholar' || $contentType === 'book'): ?><label>أساس الحقوق أو الإذن<input name="rights_basis" maxlength="500" value="<?= e((string) $row['rights_basis']) ?>" required></label><?php endif; ?>
        <?php if ($contentType === 'lesson' || $contentType === 'series'): ?><label>العالم<select name="scholar_id"><option value="0">بدون</option><?php foreach ($scholars as $scholar): ?><option value="<?= (int) $scholar['id'] ?>"<?= (int) ($row['scholar_id'] ?? 0) === (int) $scholar['id'] ? ' selected' : '' ?>><?= e($scholar['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <?php if ($contentType === 'lesson'): ?><label>السلسلة<select name="series_id"><option value="0">بدون</option><?php foreach ($seriesItems as $seriesItem): ?><option value="<?= (int) $seriesItem['id'] ?>"<?= (int) ($row['series_id'] ?? 0) === (int) $seriesItem['id'] ? ' selected' : '' ?>><?= e($seriesItem['title']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <?php if ($contentType === 'book'): ?><label>استبدال ملف PDF<input type="file" name="book_pdf" accept="application/pdf,.pdf"></label><label class="check-label"><input type="checkbox" name="can_download"<?= $row['can_download'] ? ' checked' : '' ?>> مسموح بالتنزيل</label><?php endif; ?>
        <?php if ($contentType !== 'book'): ?><label>ترتيب العرض<input type="number" name="sort_order" min="-100000" max="100000" value="<?= (int) ($row['sort_order'] ?? 0) ?>"></label><?php endif; ?>
        <label class="check-label"><input type="checkbox" name="publish"<?= $row['is_published'] ? ' checked' : '' ?>> نشر</label><button class="button button-primary" type="submit">حفظ التعديلات</button>
    </form>
</details>
